===== EnsureUniqueIdentity =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * Rejects a create request whose derived {@link IdentityKey identity key} exactly equals an existing
 * owner's — the single consolidated duplicate check that replaces the separate telephone, email and
 * household checks. Runs after the telephone and email are normalized and the household id assigned
 * (see {@link AssignHousehold}), so the built owner already carries its final key parts. Because the
 * telephone is part of the key, two members of one household with different telephones have distinct
 * keys and are both allowed; only a full-key match is a 409 via {@link DuplicateIdentityException}.
 */
public class EnsureUniqueIdentity {

    public void service(@Val Owner owner, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        String identityKey = IdentityKey.forOwner(owner);
        for (Owner existing : ownerRepository.findAll()) {
            if (identityKey.equals(IdentityKey.forOwner(existing))) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }
}
===== IdentityKey =====
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single derived duplicate-detection key for owners: the canonical telephone, the canonical email
 * (empty when absent) and the household id (empty when the owner is in no shared household), joined by
 * '|'. {@link EnsureUniqueIdentity} rejects a create request whose whole key equals an existing
 * owner's, and {@link org.springframework.samples.petclinic.mapper.OwnerMapper} returns it on the
 * response. Consolidating telephone, email and household into one key means two owners collide only on
 * an exact full-key match: sharing a household (same household id) but differing in telephone yields
 * different keys and is allowed. Not a pipeline step, so it exposes plain helpers.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    /** The identity key of an existing or freshly built owner. */
    public static String forOwner(Owner owner) {
        return of(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
    }

    /**
     * Builds the identity key from its parts: the telephone in canonical E.164 form (see
     * {@link TelephoneNormalizer}), the email lower-cased or empty when absent or blank (see
     * {@link EmailNormalizer}) and the household id or empty when absent, separated by '|'.
     */
    public static String of(String telephone, String email, String householdId) {
        return normalizeTelephone(telephone) + "|" + normalizeEmail(email) + "|" + orEmpty(householdId);
    }

    private static String normalizeTelephone(String telephone) {
        String e164 = TelephoneNormalizer.toE164(telephone);
        return e164 == null ? orEmpty(telephone) : e164;
    }

    private static String normalizeEmail(String email) {
        return (email == null || email.isBlank()) ? "" : EmailNormalizer.normalize(email);
    }

    private static String orEmpty(String value) {
        return value == null ? "" : value;
    }
}
===== CountHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records how many owners the new owner's household will hold once this create completes — the new
 * owner plus every existing owner sharing the same household (same last name and address, compared
 * via {@link HouseholdNormalizer}). Runs before {@link SaveOwner}, so the new
 * owner is not yet persisted and is counted explicitly. Mutates the built {@link Owner} in place.
 */
public class CountHousehold {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String key = HouseholdNormalizer.key(owner.getLastName(), owner.getAddress());
        int members = 1;
        for (Owner existing : ownerRepository.findAll()) {
            if (key.equals(HouseholdNormalizer.key(existing.getLastName(), existing.getAddress()))) {
                members++;
            }
        }
        owner.setHouseholdSize(members);
    }
}
===== CountNamesakes =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records how many existing owners already shared the new owner's first and last name (compared
 * case-insensitively) at the moment of creation. Runs before {@link SaveOwner}, so the count
 * excludes the owner currently being created. Mutates the built {@link Owner} in place.
 */
public class CountNamesakes {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int namesakes = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
                    && owner.getLastName().equalsIgnoreCase(existing.getLastName())) {
                namesakes++;
            }
        }
        owner.setNamesakeCount(namesakes);
    }
}
